var EXTRA=[{dot:"green",j:"Orthopaedic Journal of Sports Medicine",h:"Dopo il LCA il carico osseo si sposta verso il centro, non sparisce",v:"Studio giapponese su 17 ricostruzioni a doppio fascio: la densità ossea subcondrale posteromediale scende dopo l'intervento, ma la quota mediale sale — uno spostamento del carico, non una sua eliminazione.",pmid:'42719423',doi:'10.1177/23259671261442597',temi:["lca", "biomeccanica", "osso subcondrale"]},{dot:"green",j:"Orthopaedic Journal of Sports Medicine",h:"Un modello di IA prevede chi fallirà il trattamento senza chirurgia della radice meniscale",v:"Rete neurale coreana su 233 pazienti trattati senza intervento: buona capacità predittiva del fallimento clinico a 2 e 5 anni, usando dati clinici e di imaging già disponibili in ambulatorio.",pmid:'42719366',doi:'10.1177/23259671261470935',temi:["menisco", "root", "intelligenza artificiale"]},{dot:"green",j:"Arthroscopy",h:"Innesto osseo su misura per riempire i tunnel prima della revisione del LCA",v:"Serie retrospettiva americana: un allograft di testa e collo femorale sagomato a mano riempie bene i difetti osteolitici dei tunnel prima della revisione in due tempi, con un costo inferiore ai dowel prefabbricati.",pmid:'42720144',doi:'10.1002/arj.70540',temi:["lca", "revisione", "innesto osseo"]},{dot:"green",j:"Arthroscopy",h:"Nella displasia trocleare severa, i due indici classici di patella alta litigano",v:"Su 152 ginocchia operate per instabilità femoro-rotulea, l'indice RM e quello radiografico di altezza rotulea concordano bene nei trocleari normali ma divergono nella displasia di alto grado.",pmid:'42721022',doi:'10.1002/arj.70549',temi:["rotula", "displasia trocleare", "diagnostica per immagini"]},{dot:"gray",j:"Clinical Journal of Sport Medicine",h:"Il dibattito sulla guarigione del crociato senza chirurgia continua",v:"Una lettera metodologica contesta un lavoro che aveva già messo in dubbio il Cross Bracing Protocol, il tutore che secondo alcuni farebbe guarire il crociato senza intervento: la disputa scientifica resta aperta.",pmid:'42714927',doi:'10.1097/JSM.0000000000001502',temi:["lca", "trattamento conservativo", "dibattito scientifico"]},{dot:"green",j:"Arthroscopy, Sports Medicine, and Rehabilitation",h:"Il nuovo artrometro GNRB non sostituisce ancora il KT1000 nel LCA",v:"In 20 pazienti, alta concordanza fra osservatori con il nuovo dispositivo, ma sensibilità diagnostica nettamente inferiore al KT1000 nell'identificare la lassità del crociato prima dell'intervento.",pmid:'42712905',doi:'10.1002/ars2.70056',temi:["lca", "artrometria", "diagnostica"]},{dot:"gray",j:"Journal of Human Kinetics",h:"Nell'atterraggio laterale, la gamba non dominante carica di più",v:"In venti atleti attivi, l'arto non dominante mostra un momento in valgo del ginocchio più alto durante l'atterraggio da un salto laterale su una gamba: un possibile fattore di rischio biomeccanico per il crociato.",pmid:'42712731',doi:'10.5114/jhk/205897',temi:["lca", "prevenzione infortuni", "biomeccanica"]},{dot:"gray",j:"Journal of Medical Internet Research",h:"La realtà estesa aiuta di più nell'artrosi che dopo la protesi",v:"Revisione sistematica: la riabilitazione digitale interattiva sembra utile nel dolore da artrosi di ginocchio, mentre dopo la protesi totale l'evidenza resta più incerta e con pochi studi.",pmid:'42714169',doi:'10.2196/84753',temi:["realtà virtuale", "riabilitazione", "protesi totale"]},{dot:"green",j:"Frontiers in Physiology",h:"La condromalacia rotulea dopo il LCA frena il rientro allo sport",v:"In 80 pazienti operati con hamstring, chi sviluppa condromalacia rotulea nel primo anno ha più dolore, meno forza del quadricipite e performance peggiori nei test di salto usati per decidere il rientro.",pmid:'42712558',doi:'10.3389/fphys.2026.1931981',temi:["lca", "rotula", "rientro allo sport"]},{dot:"green",j:"Chinese Journal of Reparative and Reconstructive Surgery",h:"In Cina, gli osteofiti tibiali posteromediali confondono il bilanciamento robotico",v:"Analisi retrospettiva cinese su 82 protesi robot-assistite: gli spazi articolari misurati dal robot dopo l'osteotomia si allargano rispetto al piano, in proporzione alla dimensione degli osteofiti posteromediali non ancora resecati.",pmid:'42642193',doi:'10.7507/1002-1892.202602049',temi:["protesi ginocchio", "robotica", "bilanciamento spazi"]},{dot:"green",j:"Acta Orthopaedica",h:"Una lieve rigidità in flessione prima della mono non peggiora il risultato",v:"In 1.199 protesi monocompartimentali danesi, una flessione contratta lieve o una flessione limitata prima dell'intervento rallentano il recupero iniziale ma non impediscono di raggiungere lo stesso risultato funzionale a due anni.",pmid:'42713985',doi:'10.2340/17453674.2026.46721',temi:["protesi parziale", "monocompartimentale", "recupero funzionale"]},{dot:"green",j:"Journal of Orthopaedic Case Reports",h:"La risonanza riconosce bene le lesioni della radice, ma non sempre",v:"Studio prospettico indiano su 50 pazienti: buona accuratezza diagnostica della risonanza magnetica nel riconoscere le lesioni della radice meniscale rispetto all'artroscopia, che resta il riferimento definitivo.",pmid:'42713124',doi:'10.13107/jocr.2026.v16.i09.8136',temi:["menisco", "root", "diagnostica per immagini"]},{dot:"gray",j:"Journal of Orthopaedic Case Reports",h:"La riparazione biologica del crociato resta un'opzione selettiva, non la regola",v:"Una rassegna narrativa sul Bridge-Enhanced ACL Repair conferma dati incoraggianti ma preliminari: resta indicata solo in lesioni acute e riparabili con buon moncone tibiale, mentre la ricostruzione con innesto resta la scelta per i casi complessi o cronici.",pmid:'42713426',doi:'10.13107/jocr.2026.v16.i09.8160',temi:["lca", "riparazione biologica", "tecniche emergenti"]},{dot:"gray",j:"Cureus",h:"Rinforzare l'innesto del crociato con un donatore non convince ancora",v:"Meta-analisi di 17 studi: nessuna differenza clinicamente rilevante fra innesti ibridi allograft/autograft e autograft isolato, con un segnale non definitivo di più fallimenti nel gruppo ibrido.",pmid:'42718911',doi:'10.7759/cureus.114231',temi:["lca", "innesto", "allograft"]},{dot:"gray",j:"Bone & Joint Research",h:"Bi-mono o protesi totale: il movimento reale non cambia molto",v:"Analisi secondaria di un trial randomizzato: l'attività fisica misurata con un sensore indossabile migliora dopo entrambe le protesi, senza una differenza chiara fra le due tecniche a uno e due anni.",pmid:'42717773',doi:'10.1302/2046-3758.159.BJR-2026-0018.R1',temi:["protesi ginocchio", "attività fisica", "monocompartimentale"]}];
var SCOPERTE=[{t:"Un'intelligenza artificiale che impara a simulare il ginocchio, non solo a leggerlo",v:"Una rassegna cinese di bioingegneria descrive i primi tentativi di addestrare modelli di intelligenza artificiale capaci di stimare stress e carichi nel ginocchio più rapidamente delle simulazioni classiche a elementi finiti. È ricerca metodologica, lontana dall'uso clinico: nessun modello è oggi validato su una meccanica multi-tessuto realistica, e gli autori stessi chiedono dati tracciabili e una verifica con la simulazione classica per ogni caso fuori dal range di addestramento.",pmid:'42623379',doi:'10.1177/09544119261477934',temi:["intelligenza artificiale", "bioingegneria", "simulazione biomeccanica"]},{t:"In Cina, l'intelligenza artificiale prova a vedere l'artrosi prima che si veda",v:"Una rassegna di ingegneria biomedica di Tianjin descrive come modelli di deep learning stiano imparando a combinare radiografie, risonanza, dati clinici e del cammino per riconoscere l'artrosi di ginocchio nelle sue fasi più precoci, quando i segni radiografici sono ancora atipici. Gli stessi autori avvertono che il valore aggiunto rispetto ai singoli esami resta da confermare con studi multicentrici e definizioni condivise di «fase precoce».",pmid:'42656119',doi:'10.7507/1001-5515.202601026',temi:["intelligenza artificiale", "artrosi precoce", "mondo orientale"]},{t:"Un plantare robotico che corregge il passo, un passo alla volta",v:"Un piccolo studio giapponese descrive un dispositivo robotico indossabile nella scarpa che corregge in tempo reale l'allineamento della caviglia durante il passo, riducendo l'instabilità dell'appoggio in pazienti con artrosi del comparto mediale. È un'analisi esplorativa su sei pazienti, lontana dall'uso clinico, ma un'idea concreta su come la robotica indossabile possa affiancare — non sostituire — la chirurgia nella gestione del carico articolare.",pmid:'42656284',doi:'10.3389/frobt.2026.1898805',temi:["robotica indossabile", "riabilitazione del passo", "bioingegneria"]}];
var SOC={"1": {"video": "Una serie retrospettiva su 53 riparazioni della radice meniscale posteriore mediale, in un centro di riferimento terziario, mostra un fallimento nel 22,6 per cento dei casi a un anno. Tre segnali preoperatori pesano di più: sesso femminile, edema osseo tibiale alla risonanza, e un grado più alto di usura cartilaginea nel comparto mediale. Età, peso corporeo, tipo di fissazione e persino l'estrusione preoperatoria — la variabile più discussa in letteratura — non fanno differenza in questo campione. Quando la riparazione riesce, il miglioramento clinico a due anni è netto: la scala del dolore scende di oltre la metà e il punteggio funzionale quasi si raddoppia. È uno studio piccolo, di un solo centro: un primo profilo di rischio da discutere in ambulatorio, non ancora una regola clinica."}, "2": {"video": "Una Current Concepts Review su Journal of ISAKOS affronta per la prima volta in modo organico i sintomi neurologici dopo riparazione meniscale: sensibilità alterata, dolore neuropatico, deficit motori, in rari casi permanenti. Gli autori propongono un percorso di sospetto clinico stratificato per rischio, che tiene conto di come è stato eseguito l'intervento, del tipo di anestesia e del momento in cui compaiono i sintomi, integrando esame seriale, ecografia ad alta risoluzione, neurografia RM ed elettrodiagnostica quando serve. È una revisione narrativa, livello V: gli stessi autori dichiarano che l'evidenza resta scarsa, fatta soprattutto di casi isolati. Ma è il primo tentativo di dare una struttura condivisa a una complicanza rara della riparazione meniscale, tecnica che pratichi regolarmente."}, "3": {"video": "In 109 ginocchia operate di osteotomia tibiale alta a V invertita per varo severo, correggere di più — fino a quasi 19 gradi — non prolunga i tempi di guarigione dell'osso né aumenta le complicanze rispetto a correzioni più piccole: 12,7 contro 12,4 settimane di consolidamento, 4,1 contro 3,3 per cento di complicanze, nessuna differenza sui punteggi funzionali. Il numero di eventi osservati resta basso in entrambi i gruppi, quindi lo studio non può escludere del tutto un rischio più alto nella correzione ampia — ricalcolato con il metodo della potenza statistica, l'intervallo va da un forte vantaggio a un rischio quasi ottuplicato. Resta comunque un segnale incoraggiante per chi opera correzioni importanti su ginocchia molto deformate."}, "4": {"video": "In 203 ginocchia operate di protesi monocompartimentale mediale, seguite per quasi sei anni in media, la fragilità preoperatoria — misurata con una scala clinica semplice già disponibile in ambulatorio — predice in modo indipendente la progressione artrosica del compartimento laterale, quello non sostituito dalla protesi: un rischio più che quadruplo rispetto ai pazienti robusti, con punteggi funzionali finali significativamente peggiori su tutte le scale usate. I dati radiografici completi a cinque anni erano però disponibili solo per meno della metà della coorte, un limite da tenere presente. Resta un primo strumento pratico, semplice da applicare, per impostare il colloquio preoperatorio sul rischio di dover convertire a protesi totale nel tempo."}, "5": {"video": "Una revisione sistematica con protocollo registrato confronta fissazione cementata e non cementata nella protesi totale di ginocchio robot-assistita, su dieci studi comparativi: il rischio relativo di revisione a medio termine è 0,63, ma con un intervallo di confidenza così ampio — da 0,09 a 4,53 — da non escludere né un forte vantaggio né un rischio quasi quintuplicato del non cementato. Anche il tempo operatorio e la durata della degenza restano stime imprecise e molto eterogenee. La certezza dell'evidenza è dichiarata molto bassa su ogni singolo esito: un messaggio onesto più che un verdetto. La scelta fra cementare o no nella protesi robotica resta, oggi, affidata al giudizio clinico, non a una prova solida."}, "6": {"video": "Uno studio caso-controllo su 284 ginocchia introduce un nuovo parametro alla risonanza magnetica, basato sull'inclinazione del tendine rotuleo, per l'instabilità femoro-rotulea negli adolescenti. Il nuovo indice, insieme a un secondo parametro simile già proposto in letteratura, distingue bene chi ha instabilità da chi no, con una buona accuratezza diagnostica, e resta informativo anche quando la misura classica dell'allineamento della tuberosità tibiale è normale. È uno studio diagnostico, non chirurgico: non valuta l'esito di un intervento, ma arricchisce il work-up preoperatorio dei tuoi pazienti adolescenti candidati a una ricostruzione del legamento patello-femorale mediale."}};
var SOCV={"1": {"video": {"chir": ["Una serie retrospettiva su 53 riparazioni artroscopiche della radice meniscale posteriore mediale, in un centro di riferimento terziario, misura il tasso di fallimento a un anno: 12 pazienti su 53, il 22,6 per cento, fra ri-rottura e conversione a protesi.", "Tre variabili preoperatorie si associano al fallimento: sesso femminile, presente nel 92 per cento dei fallimenti contro il 63 dei successi; edema osseo tibiale alla risonanza, 58 contro 12 per cento; e un grado Outerbridge del comparto mediale più alto, 2,8 contro 1,9. Età, indice di massa corporea, metodo di fissazione ed estrusione preoperatoria non differiscono fra i due gruppi.", "È una serie piccola, monocentrica, senza gruppo di controllo: i numeri vanno letti come un primo profilo di rischio, non come una regola clinica. Ma chi ha successo migliora in modo netto: la scala del dolore scende da 4,9 a 2,1, e il punteggio funzionale SANE sale da 51,7 a 80,8 punti a due anni."], "misto": ["Quando si ripara la radice del menisco interno con la tecnica transtibiale, in circa un caso su cinque la sutura non tiene entro un anno. Uno studio su 53 pazienti operati in un centro specializzato ha cercato di capire chi rischia di più.", "Tre segnali, visibili già prima dell'intervento, compaiono più spesso in chi poi fallisce: essere donna, avere un gonfiore dell'osso della tibia visibile alla risonanza, e avere più usura della cartilagine nel comparto interno del ginocchio. Età e peso corporeo, invece, non sembrano contare.", "Sono numeri da un solo centro e da un campione limitato, quindi vanno presi con cautela. Ma il messaggio pratico è utile: quando questi tre segnali sono presenti, vale la pena discuterne apertamente con il paziente prima di operare, sapendo che comunque, quando la riparazione riesce, il miglioramento clinico a due anni è netto."], "pazienti": ["Il menisco interno del ginocchio ha una radice che lo ancora all'osso: quando si lacera, oggi si può riparare con un piccolo intervento in artroscopia. Uno studio ha seguito 53 persone operate con questa tecnica per capire come va nel tempo.", "Nella maggior parte dei casi la riparazione ha funzionato bene: il dolore è diminuito molto e la funzione del ginocchio è migliorata in modo netto a due anni dall'intervento. In alcuni casi, però, la sutura non ha tenuto.", "Lo studio ha individuato alcuni segnali, visibili già prima dell'operazione con la risonanza magnetica e con l'esame clinico, che erano più frequenti in chi poi ha avuto bisogno di un secondo intervento. Sono indicazioni utili per il colloquio col chirurgo, non certezze: lo studio è piccolo e fatto in un solo ospedale."]}, "linkedin": {"chir": ["Serie retrospettiva monocentrica, 53 riparazioni artroscopiche della radice meniscale posteriore mediale, follow-up minimo 1 anno: tasso di fallimento (ri-rottura o conversione a protesi) 22,6% (12/53).", "Predittori univariati di fallimento: sesso femminile (92% vs 63%, p=0,033), edema osseo tibiale preoperatorio (58% vs 12%, p=0,001), Outerbridge mediale più alto (2,8±0,9 vs 1,9±1,1, p=0,015). Non associati: età, BMI, metodo di fissazione, estrusione preoperatoria — quest'ultima è il dato che sorprende di più, dato il peso che ha in letteratura.\n\nNei successi, miglioramento netto: VAS da 4,9 a 2,1, SANE da 51,7 a 80,8 a 2 anni (p<0,001 per entrambi).", "Limiti dichiarati: livello IV, monocentrico, 12 eventi totali — le stime di associazione restano imprecise e non generano una regola prescrittiva. Ma sono tre variabili facilmente disponibili in ambulatorio, utili per un colloquio preoperatorio più informato con le pazienti a rischio più alto.\n\nWynveen, Henson-Vendrell, Glover et al., Arthroscopy Sports Med Rehabil, settembre 2026."], "misto": ["Riparare la radice del menisco interno funziona bene, ma non sempre: in una serie di 53 pazienti operati in un centro specializzato, la sutura non ha tenuto in circa 1 caso su 5 entro un anno.", "Tre elementi, già visibili prima dell'operazione, erano più frequenti in chi poi ha avuto un fallimento: essere donna, avere un gonfiore dell'osso visibile alla risonanza, avere più usura della cartilagine. Non hanno pesato invece età, peso corporeo e tecnica di fissazione.\n\nQuando la riparazione riesce, il beneficio è netto sia sul dolore sia sulla funzione, misurato a due anni.", "È uno studio di un solo centro, su un numero limitato di pazienti: i tre segnali vanno letti come un punto di partenza per il colloquio con il chirurgo, non come una previsione certa."], "pazienti": ["Riparare il menisco interno del ginocchio: cosa dice la scienza su quando funziona meglio", "Uno studio ha seguito 53 persone operate per riparare la radice del menisco interno, la parte che lo tiene ancorato all'osso. Nella maggior parte dei casi l'intervento ha dato buoni risultati, con meno dolore e più funzione a due anni.", "In alcuni casi la riparazione non ha tenuto. I ricercatori hanno notato che questo succedeva un po' più spesso in presenza di alcuni segnali visibili già prima dell'operazione. Sono indicazioni utili da discutere col proprio chirurgo, non regole fisse: lo studio riguarda un numero limitato di persone."]}, "instagram": {"chir": ["Radice meniscale mediale: chi rischia di più dopo la sutura?\nSerie retrospettiva, 53 pazienti: fallimento nel 22,6% a 1 anno.", "Tre segnali preoperatori pesano di più: sesso femminile, edema osseo tibiale alla RM, grado di usura cartilaginea (Outerbridge) più alto.\nNon pesano: età, peso corporeo, tipo di fissazione — e, sorpresa, nemmeno l'estrusione preoperatoria.", "Quando la riparazione riesce, il miglioramento clinico a 2 anni è netto.\nStudio piccolo, un solo centro: un primo profilo di rischio, non una regola."], "misto": ["Sutura della radice meniscale: cosa dice la scienza\nIn 53 pazienti operati, la sutura non tiene in circa 1 caso su 5 entro un anno.", "Tre segnali prima dell'intervento sembrano contare: essere donna, gonfiore osseo alla risonanza, più usura della cartilagine.\nNon contano età, peso, tipo di fissazione.", "Quando la riparazione funziona, il miglioramento a due anni è netto.\nStudio piccolo, un solo centro: primo indizio, non regola."], "pazienti": ["Riparare il menisco: quando funziona meglio?\nUno studio ha seguito 53 persone operate per riparare la radice del menisco interno.", "Nella maggioranza dei casi, meno dolore e più funzione dopo due anni.\nIn alcuni casi la sutura non ha tenuto: più spesso in presenza di alcuni segnali visibili già prima dell'intervento.", "Utile parlarne col proprio chirurgo — non è una previsione certa, lo studio è piccolo."]}, "reel": {"chir": ["[SUTURA DELLA RADICE MENISCALE — CHI RISCHIA DI PIÙ] 53 pazienti, follow-up a 1 anno: il 22,6% fallisce, fra ri-rottura e protesi.", "[TRE SEGNALI PRIMA DELL'INTERVENTO] Sesso femminile, edema osseo tibiale alla risonanza, cartilagine più usurata (Outerbridge alto): tutti più frequenti in chi poi fallisce.", "[E QUELLO CHE NON CONTA] Età, peso, tipo di fissazione, estrusione preoperatoria — nessuna differenza. Campione piccolo, un solo centro: un primo indizio, non un verdetto."], "misto": ["[MENISCO: LA RIPARAZIONE TIENE?] 53 pazienti, 1 anno di controllo: nel 78% dei casi sì.", "[COSA PESA DI PIÙ] Essere donna, un gonfiore dell'osso visibile alla risonanza, più usura della cartilagine — tutti più comuni in chi poi ha un fallimento.", "[QUANDO FUNZIONA] Il miglioramento è netto: meno dolore, più funzione a due anni. Studio piccolo, un centro solo: da confermare."], "pazienti": ["[IL MENISCO SI PUÒ RIPARARE] Uno studio ha seguito 53 persone operate alla radice del menisco interno.", "[COME È ANDATA] Nella maggior parte dei casi, molto meglio dopo due anni. In alcuni casi la sutura non ha tenuto.", "[COSA SAPERE PRIMA] Alcuni segnali visibili prima dell'operazione erano più comuni in chi poi ha avuto bisogno di un secondo intervento — parlane col tuo chirurgo."]}}, "2": {"video": {"chir": ["Una Current Concepts Review su Journal of ISAKOS affronta per la prima volta in modo organico i sintomi neurologici dopo riparazione meniscale: sensibilità alterata, dolore neuropatico, deficit motori, occasionalmente permanenti.", "Gli autori propongono un framework di sospetto clinico stratificato per rischio, che integra fenotipo neurologico, fattori procedura-specifici — anestesia regionale, laccio emostatico, posizionamento dei portali, tecnica di riparazione — esame seriale, imaging con ecografia ad alta risoluzione o neurografia RM, ed elettrodiagnostica quando serve.", "È una revisione narrativa, livello V: gli stessi autori dichiarano che l'evidenza disponibile resta prevalentemente anatomica, tecnica o aneddotica, senza stime di incidenza affidabili né soglie diagnostiche validate. Serve più come cornice di sospetto che come protocollo pronto all'uso."], "misto": ["Riparare il menisco, con suture o con la rifissazione della radice, è un intervento sicuro, ma in casi rari possono comparire disturbi ai nervi vicini: formicolii, dolore anomalo, difficoltà a muovere il piede.", "Un gruppo di esperti ha messo insieme per la prima volta un quadro chiaro di quando sospettare questi problemi e come indagarli, tenendo conto di come è stato fatto l'intervento e del tipo di anestesia usata.", "Non ci sono ancora numeri affidabili su quanto spesso succeda: la letteratura, dicono gli stessi autori, resta fatta soprattutto di casi isolati. È comunque un primo passo verso un modo condiviso di riconoscere e gestire questi rari eventi."], "pazienti": ["Dopo un intervento per riparare il menisco, in rari casi può capitare di avvertire formicolii, un dolore insolito o una difficoltà a muovere una parte del piede, per un piccolo disturbo di un nervo vicino alla zona operata.", "Un gruppo internazionale di specialisti ha messo insieme le conoscenze attuali su come riconoscere questi segnali il prima possibile e su quando è opportuno un accertamento in più, come un'ecografia o un esame della conduzione nervosa.", "È una complicanza non comune, e nella grande maggioranza dei casi migliora da sola con il tempo. Conoscerla aiuta a non allarmarsi e a saperne parlare con il chirurgo se un sintomo di questo tipo dovesse comparire."]}, "linkedin": {"chir": ["Sintomi neurologici dopo riparazione meniscale: la prima cornice organica di sospetto clinico.", "Current Concepts Review su J ISAKOS: framework esperto stratificato per rischio che integra fenotipo neurologico, fattori procedura-specifici (anestesia regionale, laccio emostatico, portali, tecnica di riparazione), esame clinico seriale, ecografia ad alta risoluzione, neurografia RM, studi di conduzione ed elettromiografia nei casi sospetti.\n\nIl timing postoperatorio va letto come modificatore del sospetto clinico, non come criterio isolato per distinguere un fenomeno transitorio da una lesione strutturale.", "Livello V, nessun dato originale: gli stessi autori definiscono l'evidenza disponibile prevalentemente anatomica, tecnica o aneddotica, senza stime di incidenza affidabili né soglie diagnostiche validate. Serve come euristica clinica generatrice di ipotesi, non come protocollo definitivo — ma è la prima volta che il tema viene organizzato in modo sistematico.\n\nRivarola, Collazo, Palanconi et al., J ISAKOS, settembre 2026."], "misto": ["Sintomi neurologici dopo la sutura del menisco: finalmente una guida chiara su quando preoccuparsi.", "Una revisione di esperti mette insieme, per la prima volta in modo organico, come riconoscere i disturbi ai nervi — formicolii, dolore anomalo, difficoltà motorie — che possono comparire dopo una riparazione meniscale, complicanza rara ma da conoscere.\n\nIl framework tiene conto di come è stato eseguito l'intervento, del tipo di anestesia e del momento in cui compaiono i sintomi.", "Non porta dati numerici nuovi: la letteratura su questo tema resta scarsa, fatta soprattutto di casi isolati. È però il primo tentativo di dare una struttura condivisa a un problema finora affrontato caso per caso."], "pazienti": ["Un raro disturbo ai nervi dopo la riparazione del menisco: come riconoscerlo presto.", "In casi rari, dopo l'intervento per riparare il menisco può comparire un formicolio, un dolore insolito o una debolezza in una parte del piede o della gamba, per un piccolo disturbo del nervo vicino alla zona operata.", "Un gruppo di specialisti internazionali ha messo insieme le conoscenze su come riconoscere questi segnali il prima possibile. È una complicanza non comune e, nella maggior parte dei casi, si risolve da sola nel tempo."]}, "instagram": {"chir": ["Sintomi neurologici dopo sutura meniscale: la prima guida organica.\nCurrent Concepts Review, J ISAKOS: framework di sospetto stratificato per rischio.", "Fenotipo neurologico + fattori procedurali + esame seriale + imaging mirato.\nIl timing è un modificatore del sospetto, non un criterio isolato.", "Livello V: evidenza ancora scarsa, soprattutto case report.\nPrimo tentativo di dare una struttura condivisa al problema."], "misto": ["Sutura del menisco: un raro disturbo ai nervi, spiegato bene.\nFormicolii, dolore anomalo, difficoltà motorie: rari ma possibili dopo la riparazione.", "Una guida di esperti aiuta a riconoscerli e a sapere quando indagare.\nConta il tipo di intervento, l'anestesia e il momento in cui compare il sintomo.", "Ancora pochi dati numerici: la letteratura è scarsa.\nPrimo passo verso un modo condiviso di gestire questi casi."], "pazienti": ["Dopo la riparazione del menisco: un raro disturbo ai nervi.\nIn casi rari può comparire formicolio o debolezza in una parte del piede.", "Un gruppo di specialisti spiega quando sospettarlo e come indagare.\nÈ raro, e nella maggior parte dei casi si risolve da solo.", "Parlane col tuo chirurgo se noti un sintomo di questo tipo dopo l'intervento."]}, "reel": {"chir": ["[SUTURA MENISCALE E NERVI] Prima guida organica sui sintomi neurologici post-riparazione, J ISAKOS.", "[COSA GUARDARE] Fenotipo neurologico, anestesia, laccio, portali, tecnica — un framework di sospetto stratificato.", "[IL LIMITE] Livello V, evidenza ancora scarsa: primo tentativo di darle una struttura."], "misto": ["[UN RARO PROBLEMA AI NERVI] Dopo la sutura del menisco, di rado, formicolio o debolezza.", "[LA NOVITÀ] Una guida di esperti spiega quando sospettarlo e come indagare.", "[IL LIMITE] Pochi dati numerici finora: è un primo passo condiviso."], "pazienti": ["[MENISCO: UN RARO EFFETTO SUI NERVI] Formicolio o debolezza dopo l'intervento, di rado.", "[COSA FARE] Parlane col chirurgo: si riconosce e quasi sempre si risolve da solo.", "[PERCHÉ CONTA] Una guida internazionale aiuta ora a riconoscerlo presto."]}}, "3": {"video": {"chir": ["Una coorte di 109 ginocchia operate di osteotomia tibiale alta a V invertita, con placca bloccata, confronta correzioni ampie — 13 fino a 19 gradi — con correzioni più piccole nel varo severo.", "Nessuna differenza significativa fra i due gruppi su tempo di consolidamento, 12,7 contro 12,4 settimane, tasso di complicanze, 4,1 contro 3,3 per cento, punteggio Lysholm e nessuna delle cinque sottoscale KOOS. Entrambi i gruppi migliorano in modo significativo rispetto al preoperatorio.", "Con il calcolo di potenza sui conteggi grezzi, il rischio relativo delle complicanze ha un intervallo di confidenza da 0,18 a 8,38 — non esclude un rischio anche molto più alto nella correzione ampia. Resta comunque un dato incoraggiante per chi opera correzioni importanti su ginocchia molto deformate."], "misto": ["Quando il ginocchio è molto storto verso l'interno per l'artrosi, a volte serve correggere di molto l'asse della gamba con un intervento chiamato osteotomia tibiale alta.", "Uno studio su 109 interventi mostra che le correzioni più importanti, fino quasi a 19 gradi, guariscono altrettanto bene di quelle più piccole, senza più complicazioni né tempi di recupero più lunghi.", "Il numero di complicazioni osservate è basso in entrambi i gruppi, quindi lo studio non può escludere del tutto un rischio più alto nella correzione ampia: il segnale è incoraggiante, ma non del tutto definitivo."], "pazienti": ["Quando il ginocchio è molto deformato verso l'interno per l'artrosi, un intervento chiamato osteotomia può raddrizzare l'asse della gamba, spostando il peso lontano dalla parte più usurata.", "Uno studio su oltre cento interventi mostra che, anche quando serve una correzione importante dell'asse, l'osso guarisce bene e le complicazioni non aumentano rispetto alle correzioni più piccole.", "È una buona notizia per chi ha bisogno di una correzione consistente: l'intervento resta sicuro, anche se lo studio, per numeri limitati, non può garantirlo con assoluta certezza."]}, "linkedin": {"chir": ["Osteotomia tibiale alta nel varo severo: correggere di più non costa in complicanze.", "Coorte di 109 ginocchia, tecnica iVHTO con placca bloccata: correzione ampia (≥13°, media 15,6°) vs correzione minore (<13°, media 10,5°). Nessuna differenza su consolidamento (12,7 vs 12,4 settimane), complicanze (4,1% vs 3,3%), Lysholm (93 vs 96,5) o le cinque sottoscale KOOS.", "Livello III, singolo centro. Con `test/potenza.py` sui conteggi grezzi delle complicanze (2/49 vs 2/60): RR 1,22, IC 95% 0,18-8,38 — l'intervallo non esclude un rischio anche molto più alto nella correzione ampia. Il dato resta comunque rassicurante per la pratica quotidiana su ginocchia molto deformate.\n\nYasuda, Yabuuchi, Kondo et al., OJSM, settembre 2026."], "misto": ["Correggere molto la gamba storta, senza pagarla in complicazioni.", "Uno studio su 109 interventi di correzione dell'asse della gamba (osteotomia) per artrosi da varo severo mostra che le correzioni più importanti — fino a quasi 19 gradi — guariscono bene quanto quelle più piccole, senza differenze nei tempi di recupero né nelle complicazioni.\n\nSia le correzioni ampie sia quelle piccole portano a un miglioramento clinico netto rispetto a prima dell'intervento.", "Il numero di complicazioni osservate resta basso in entrambi i gruppi: lo studio è incoraggiante ma, per la sua dimensione, non può escludere del tutto un rischio più alto nelle correzioni ampie."], "pazienti": ["Ginocchio molto storto: correggere in modo importante resta sicuro.", "Quando il ginocchio è molto deviato verso l'interno per l'artrosi, a volte serve un intervento — l'osteotomia — che corregge in modo importante l'asse della gamba. Uno studio su oltre cento interventi mostra che anche le correzioni più grandi guariscono bene, senza più complicazioni.", "È una buona notizia per chi ha un'artrosi già avanzata: l'intervento resta sicuro anche quando serve correggere molto, pur restando lo studio non del tutto definitivo per i numeri limitati."]}, "instagram": {"chir": ["Osteotomia nel varo severo: correggere di più non costa in complicanze.\n109 ginocchia, iVHTO con placca bloccata.", "Correzione ampia (fino a 19°) vs correzione minore: stesso consolidamento, stesse complicanze.\nNessuna differenza su Lysholm né sulle 5 sottoscale KOOS.", "Con potenza.py: IC 95% del RR complicanze 0,18-8,38 — non definitivo, ma incoraggiante."], "misto": ["Correggere molto la gamba storta resta sicuro.\n109 interventi di osteotomia per varo severo dell'artrosi.", "Correzioni fino a quasi 19° guariscono bene quanto quelle più piccole.\nStesse complicazioni, stesso miglioramento clinico.", "Numeri piccoli: incoraggiante, non ancora definitivo."], "pazienti": ["Ginocchio molto storto? Si può correggere in sicurezza.\nUno studio su oltre 100 interventi di osteotomia per artrosi avanzata.", "Anche le correzioni importanti guariscono bene.\nNessun aumento di complicazioni rispetto a correzioni più piccole.", "Buona notizia per chi ha bisogno di una correzione consistente."]}, "reel": {"chir": ["[OSTEOTOMIA NEL VARO SEVERO] 109 ginocchia: correggere fino a 19° non aumenta le complicanze.", "[I NUMERI] Consolidamento e complicanze identici fra correzioni ampie e piccole.", "[IL LIMITE] Eventi rari: l'IC del RR (0,18-8,38) non chiude del tutto la domanda."], "misto": ["[GAMBA MOLTO STORTA? SI CORREGGE IN SICUREZZA] 109 interventi di osteotomia per artrosi da varo severo.", "[IL DATO] Correzioni importanti guariscono come quelle piccole, stesse complicazioni.", "[IL LIMITE] Numeri piccoli: incoraggiante, non definitivo."], "pazienti": ["[QUANDO IL GINOCCHIO È MOLTO STORTO] Un intervento può raddrizzare l'asse della gamba.", "[COSA DICE LO STUDIO] Anche le correzioni importanti guariscono bene, senza più rischi.", "[IN SINTESI] Buona notizia per chi ha un'artrosi avanzata."]}}, "4": {"video": {"chir": ["Coorte retrospettiva cinese su 203 ginocchia con protesi monocompartimentale mediale Oxford Phase III, follow-up medio 70,8 mesi: la fragilità preoperatoria, misurata con la Clinical Frailty Scale, predice la progressione artrosica del compartimento laterale.", "Nel gruppo fragile, con CFS superiore a 3, la progressione di un grado Kellgren-Lawrence nel compartimento laterale compare nel 26,3 per cento dei casi contro l'11,8 nei robusti. All'analisi multivariabile la fragilità resta un predittore indipendente, con odds ratio 4,36, intervallo di confidenza 1,37-13,90.", "I punteggi funzionali finali sono peggiori nei fragili su tutte le scale usate: Oxford Knee Score, Forgotten Joint Score e Kujala. I dati radiografici a 5 anni erano però disponibili solo per il 48,8 per cento della coorte, e l'intervallo di confidenza resta ampio."], "misto": ["Nella protesi che sostituisce solo la parte interna del ginocchio, uno studio ha seguito oltre duecento pazienti per quasi sei anni in media, per capire chi rischia di più che, negli anni, si consumi anche l'altra parte del ginocchio.", "I pazienti più fragili prima dell'intervento — misurati con una scala clinica semplice, già usata in molti ospedali — hanno un rischio più che quadruplo di questa progressione, e punteggi di funzione peggiori a fine studio.", "I dati radiografici completi a cinque anni erano disponibili solo per metà della coorte, un limite da tenere presente. Ma la scala di fragilità è uno strumento facile da usare già in ambulatorio, prima ancora di decidere l'intervento."], "pazienti": ["In chi riceve una protesi che sostituisce solo la parte interna del ginocchio, uno studio ha seguito i pazienti per diversi anni per capire cosa succede, nel tempo, all'altra parte del ginocchio, quella non sostituita.", "Le persone più fragili — più anziane, con meno riserve fisiche generali — avevano più probabilità che, con gli anni, si consumasse anche quella parte, e un recupero della funzione un po' meno soddisfacente.", "Non è una controindicazione all'intervento: è un'informazione utile per il colloquio col chirurgo, così da capire in anticipo, specie nelle persone più fragili, quali aspettative avere nel tempo."]}, "linkedin": {"chir": ["Fragilità preoperatoria e progressione del compartimento laterale dopo mono mediale: 203 ginocchia, follow-up medio 70,8 mesi.", "Pazienti fragili (Clinical Frailty Scale >3) vs robusti (CFS≤3): Oxford Knee Score finale 39,39 vs 43,06 (p<0,001), Forgotten Joint Score 79,56 vs 89,40 (p<0,001), Kujala 59,88 vs 67,71 (p<0,001). Progressione Kellgren-Lawrence laterale a 5 anni: 26,3% vs 11,8% (p=0,001). All'analisi multivariabile, fragilità predittore indipendente (OR 4,36; IC 95% 1,37-13,90; p=0,013), con gradiente crescente nei livelli più alti di fragilità.", "Limiti: dati radiografici a 5 anni disponibili solo per il 48,8% della coorte (99/203), possibile selezione; intervallo di confidenza ampio. Uno strumento di fragilità semplice, già disponibile in ambulatorio, per impostare il colloquio preoperatorio sul rischio di dover convertire a protesi totale.\n\nWang, Du, Li et al., JAAOS, settembre 2026."], "misto": ["Prima della protesi parziale, la forma fisica generale conta anche per il futuro del ginocchio.", "In oltre duecento protesi che sostituiscono solo il lato interno del ginocchio, i pazienti più fragili prima dell'intervento — misurati con una scala clinica semplice — hanno un rischio più che quadruplo di veder peggiorare, negli anni, anche il lato non operato.\n\nAnche i punteggi di funzione a fine studio erano più bassi nei pazienti fragili.", "I dati completi a cinque anni erano disponibili solo per metà della coorte studiata: un limite da conoscere. Resta comunque un primo strumento pratico e già disponibile per il colloquio prima dell'intervento."], "pazienti": ["Protesi parziale del ginocchio: la forma fisica generale conta anche nel tempo.", "In chi riceve una protesi che sostituisce solo la parte interna del ginocchio, uno studio mostra che le persone più fragili hanno più probabilità che, con gli anni, si consumi anche l'altra parte del ginocchio.", "Non è una controindicazione all'operazione: è un'informazione utile da discutere col proprio chirurgo, per capire in anticipo quali aspettative avere nel tempo."]}, "instagram": {"chir": ["Fragilità preoperatoria e mono mediale: 203 ginocchia, 70,8 mesi di follow-up.\nFragili (CFS>3) vs robusti: OKS, FJS e Kujala tutti significativamente peggiori.", "Progressione K-L laterale a 5 anni: 26,3% vs 11,8%.\nAnalisi multivariabile: OR 4,36 (IC 95% 1,37-13,90) per la fragilità.", "Limite: dati a 5 anni solo sul 48,8% della coorte.\nUno strumento clinico semplice per il colloquio preoperatorio."], "misto": ["Prima della protesi parziale, conta anche la forma fisica generale.\n203 pazienti, quasi 6 anni di follow-up medio.", "I più fragili rischiano 4 volte di più il peggioramento dell'altra parte del ginocchio.\nPunteggi di funzione finali più bassi nei pazienti fragili.", "Dati completi a 5 anni solo per metà della coorte.\nUno strumento semplice, utile già in ambulatorio."], "pazienti": ["Protesi parziale: anche la forma fisica generale conta nel tempo.\nUno studio ha seguito oltre 200 pazienti per diversi anni.", "Chi era più fragile prima dell'intervento rischia di più che l'altra parte del ginocchio si usuri.", "Non è una controindicazione: è un'informazione utile per il colloquio col chirurgo."]}, "reel": {"chir": ["[MONO MEDIALE E FRAGILITÀ] 203 ginocchia: CFS>3 predice la progressione laterale (OR 4,36).", "[I NUMERI] OKS, FJS, Kujala tutti peggiori nei fragili; K-L laterale +14,5 punti percentuali a 5 anni.", "[IL LIMITE] Dati a 5 anni solo sul 48,8% della coorte, IC ampio."], "misto": ["[PROTESI PARZIALE: CONTA ANCHE LA FRAGILITÀ] 203 pazienti, quasi 6 anni di controllo.", "[IL DATO] I più fragili rischiano 4 volte di più che l'altra parte si consumi.", "[IL LIMITE] Dati completi solo su metà coorte: un primo segnale utile."], "pazienti": ["[PRIMA DELLA PROTESI PARZIALE] La forma fisica generale conta anche nel tempo.", "[COSA DICE LO STUDIO] Chi è più fragile rischia di più che l'altra parte del ginocchio si usuri.", "[COSA FARE] Parlane col chirurgo: non è una controindicazione, solo un'informazione in più."]}}, "5": {"video": {"chir": ["Una revisione sistematica con protocollo PROSPERO confronta fissazione cementata e non cementata nella protesi totale di ginocchio robot-assistita: dieci studi comparativi, undici report, ricerca fino a fine luglio 2026.", "Il rischio relativo di revisione per tutte le cause a medio termine è 0,63, ma con un intervallo di confidenza al 95 per cento che va da 0,09 a 4,53. Anche il tempo operatorio e la durata della degenza restano stime imprecise e molto eterogenee. Certezza dell'evidenza GRADE molto bassa su ogni singolo esito.", "Gli autori concludono che l'evidenza osservazionale oggi disponibile non basta a favorire una strategia rispetto all'altra. È un messaggio onesto più che un verdetto: la scelta fra cementare o no nella protesi robotica resta, per ora, affidata al giudizio clinico, non a una prova solida."], "misto": ["Nella protesi di ginocchio guidata dal robot si può fissare l'impianto con il cemento osseo oppure senza. Una revisione di dieci studi scientifici ha provato a capire quale delle due scelte dia risultati migliori.", "Il risultato più onesto è che non c'è una risposta chiara: i numeri raccolti sono compatibili sia con un vantaggio del non cementato sia con un rischio più alto, e lo stesso vale per i tempi dell'intervento.", "Gli autori stessi definiscono la certezza delle prove molto bassa per ogni singolo risultato. Non significa che le due tecniche siano uguali: significa che serve ancora ricerca più solida prima di poter dare un consiglio netto."], "pazienti": ["Nella protesi di ginocchio fatta con l'aiuto del robot, l'impianto può essere fissato con il cemento osseo oppure senza. Una revisione di dieci studi scientifici ha cercato di capire quale delle due scelte dia risultati migliori nel tempo.", "La risposta, oggi, è che non ce n'è una chiara: gli studi disponibili non permettono di dire con certezza se sia meglio l'una o l'altra tecnica.", "Questo non vuol dire che la scelta sia indifferente: vuol dire che, con le conoscenze di oggi, non esiste ancora una prova solida a favore dell'una o dell'altra. La decisione resta affidata all'esperienza del chirurgo e alle caratteristiche del singolo paziente."]}, "linkedin": {"chir": ["Cementata o non cementata nella protesi robotica: la revisione sistematica non decide, e lo dichiara.", "10 studi comparativi/11 report, protocollo PROSPERO CRD420261446055, ricerca fino al 29 luglio 2026, ROBINS-I + GRADE. RR di revisione a medio termine: 0,63 (IC 95% 0,09-4,53; I²=0%). Manipolazione in anestesia: RR 1,03 (IC 95% 0,09-11,74). Tempo operatorio: MD -12,91 min (IC 95% -36,38/10,55; I²=94,4%). Degenza: MD -0,24 giorni (IC 95% -3,67/3,19).", "Certezza GRADE molto bassa su ogni esito aggregato. Nessuna distinzione esplicita per sistema robotico nell'abstract. Il messaggio onesto per la pratica: oggi nessuna delle due strategie di fissazione è sostenuta da prove solide nella protesi totale robot-assistita.\n\nLu, Rui, Wang et al., Journal of Robotic Surgery, settembre 2026."], "misto": ["Fissare la protesi con o senza cemento: la scienza, per ora, non ha ancora deciso.", "Una revisione di dieci studi che confrontano la fissazione cementata e quella non cementata nella protesi di ginocchio robot-assistita non trova una strategia chiaramente migliore, né sul rischio di reintervento né sui tempi operatori.\n\nLa certezza delle prove è definita dagli stessi autori «molto bassa» per tutti i risultati.", "Questo significa che nuovi studi più grandi e più solidi potrebbero cambiare completamente questa conclusione. Oggi la scelta resta clinica, guidata dall'esperienza più che dai numeri."], "pazienti": ["Protesi del ginocchio: fissarla con o senza cemento non cambia, per ora, i risultati noti.", "Nella protesi di ginocchio guidata dal robot si può fissare l'impianto con il cemento osseo oppure senza. Una revisione di dieci studi scientifici non ha trovato prove sufficienti per dire quale delle due scelte dia risultati migliori nel tempo.", "Non significa che le due tecniche siano uguali: significa che, con le conoscenze attuali, non c'è ancora una risposta certa. La scelta resta affidata all'esperienza del chirurgo."]}, "instagram": {"chir": ["Cementata o non cementata nella protesi robotica?\n10 studi, protocollo PROSPERO: la revisione non decide.", "RR revisione a medio termine 0,63, ma IC 95% 0,09-4,53.\nCertezza GRADE molto bassa su ogni esito.", "Nessun vantaggio dimostrato di una strategia sull'altra.\nIl messaggio onesto: oggi la scelta resta clinica."], "misto": ["Protesi robotica: cemento sì o no?\nUna revisione di 10 studi non trova una risposta chiara.", "Né sul rischio di reintervento, né sui tempi operatori.\nCertezza delle prove definita «molto bassa».", "Serve ancora ricerca più solida.\nPer ora la scelta resta clinica, non guidata dai numeri."], "pazienti": ["Protesi del ginocchio: con o senza cemento?\nUna revisione di 10 studi scientifici lo ha analizzato.", "Non c'è ancora una risposta chiara su quale sia meglio.\nNon significa che siano uguali: manca solo la prova certa.", "La scelta resta affidata all'esperienza del chirurgo."]}, "reel": {"chir": ["[PROTESI ROBOTICA: CEMENTO SÌ O NO?] 10 studi, protocollo PROSPERO: nessuna risposta netta.", "[I NUMERI] RR revisione 0,63, ma IC 95% 0,09-4,53 — troppo largo per decidere.", "[L'ONESTÀ] Certezza GRADE molto bassa su ogni esito: la scelta resta clinica."], "misto": ["[CEMENTO O NO NELLA PROTESI ROBOTICA?] Una revisione di 10 studi non trova un vincitore.", "[COSA MANCA] Prove solide su reintervento e tempi operatori.", "[COSA SIGNIFICA] Serve ancora ricerca: oggi decide l'esperienza del chirurgo."], "pazienti": ["[PROTESI DEL GINOCCHIO: CEMENTO O NO?] Una revisione di 10 studi lo ha analizzato.", "[IL RISULTATO] Non c'è ancora una risposta chiara su quale sia meglio.", "[COSA SIGNIFICA PER TE] La scelta resta affidata all'esperienza del tuo chirurgo."]}}, "6": {"video": {"chir": ["Uno studio caso-controllo su 284 ginocchia introduce e valida un nuovo parametro RM, l'angolo di inclinazione del tendine rotuleo, accanto alla distanza tendine rotuleo-cresta trocleare laterale, per l'instabilità femoro-rotulea negli adolescenti.", "Entrambi i parametri sono significativamente più alti nei casi di instabilità rispetto ai controlli, e correlano con tilt rotuleo, indice di Caton-Deschamps e sulcus angle. L'accuratezza diagnostica è buona: area sotto la curva 0,903 per la distanza tendinea, 0,866 per il nuovo angolo.", "È uno studio diagnostico, non chirurgico: non valuta esiti dell'intervento. Ma resta informativo anche quando la distanza TT-TG classica è normale, aggiungendo un tassello al work-up preoperatorio dell'instabilità rotulea negli adolescenti."], "misto": ["Negli adolescenti con instabilità della rotula, i medici usano già diverse misure sulla risonanza magnetica per capire perché la rotula esce dal suo alloggiamento naturale.", "Uno studio propone una misura in più, basata sull'inclinazione del tendine sotto il ginocchio, che riesce a distinguere bene chi ha il problema da chi no — anche quando le misure classiche non bastano da sole a spiegare il quadro.", "È uno strumento diagnostico aggiuntivo, non ancora collegato a un esito chirurgico: aiuta a capire meglio la situazione prima di decidere l'intervento, non sostituisce il giudizio clinico."], "pazienti": ["Negli adolescenti la rotula può uscire dal suo posto naturale, un problema chiamato instabilità femoro-rotulea. Per capirne bene la causa, i chirurghi usano la risonanza magnetica insieme a diverse misure.", "Uno studio ha messo a punto una misura in più, che valuta come è orientato il tendine sotto il ginocchio, e che aiuta a riconoscere meglio il problema anche quando le misure abituali non sono chiare da sole.", "È uno strumento in più per lo studio del ginocchio prima di un'eventuale operazione per stabilizzare la rotula, non un esame che da solo decide se operare."]}, "linkedin": {"chir": ["Instabilità femoro-rotulea negli adolescenti: un nuovo indice RM basato sul tendine rotuleo.", "Studio caso-controllo, 284 ginocchia (142 instabilità, 142 controlli): PT-LTR 9,76±7,66 mm vs controlli, PTIA 22,76°±11,22°, entrambi p<0,001. Correlazione positiva con tilt rotuleo, CDI, sulcus angle. Accuratezza diagnostica: AUC 0,903 (PT-LTR, soglia 4 mm), AUC 0,866 (PTIA, soglia 16°). Informativi anche a TT-TG normale.", "Limiti: studio diagnostico, nessun esito clinico o chirurgico valutato; riproducibilità inter-osservatore non riportata nell'abstract. Un tassello in più per il work-up preoperatorio, non un sostituto dei parametri classici.\n\nCrippa, Beltrame, Beber et al., AJSM, settembre 2026."], "misto": ["Instabilità della rotula negli adolescenti: una nuova misura RM aiuta a capirne la causa.", "Uno studio su 284 ginocchia introduce due nuovi parametri, basati sul tendine sotto il ginocchio, per distinguere chi ha instabilità femoro-rotulea da chi no. L'accuratezza diagnostica è buona, e i parametri restano informativi anche quando le misure classiche sono normali.", "È uno strumento diagnostico in più, non ancora collegato a un esito chirurgico: aiuta il chirurgo a inquadrare meglio il problema prima di decidere l'intervento."], "pazienti": ["Instabilità della rotula negli adolescenti: una nuova misura aiuta a capirla meglio.", "Uno studio ha messo a punto un nuovo modo di misurare, con la risonanza magnetica, l'orientamento del tendine sotto il ginocchio, che aiuta a riconoscere meglio l'instabilità della rotula nei ragazzi.", "È un ulteriore strumento diagnostico per lo studio del ginocchio prima di un'eventuale operazione di ricostruzione del legamento che stabilizza la rotula."]}, "instagram": {"chir": ["Instabilità femoro-rotulea adolescenti: nuovo indice RM sul tendine.\n284 ginocchia, 142 instabilità vs 142 controlli.", "PT-LTR e PTIA significativamente più alti nei casi (p<0,001).\nAUC 0,903 e 0,866 — buona accuratezza diagnostica.", "Informativi anche a TT-TG normale.\nStudio diagnostico: nessun esito chirurgico valutato."], "misto": ["Rotula instabile negli adolescenti: una misura RM in più.\n284 ginocchia analizzate con un nuovo parametro.", "Aiuta a distinguere l'instabilità anche quando le misure classiche non bastano.\nBuona accuratezza diagnostica.", "Non sostituisce il giudizio clinico, lo arricchisce."], "pazienti": ["Rotula che esce dal suo posto? Una nuova misura aiuta a capire perché.\nStudio su 284 ginocchie di adolescenti con instabilità.", "Una nuova misura RM sul tendine sotto il ginocchio aiuta la diagnosi.", "Utile prima di un'eventuale operazione per stabilizzare la rotula."]}, "reel": {"chir": ["[ROTULA INSTABILE NEGLI ADOLESCENTI] Nuovo indice RM sul tendine rotuleo, 284 ginocchia.", "[I NUMERI] AUC 0,903 e 0,866 — buona accuratezza diagnostica.", "[IL PLUS] Resta informativo anche quando il TT-TG classico è normale."], "misto": ["[PERCHÉ LA ROTULA ESCE DAL SUO POSTO?] Una nuova misura RM aiuta a capirlo.", "[LO STUDIO] 284 ginocchia di adolescenti, buona accuratezza diagnostica.", "[COSA CAMBIA] Uno strumento in più per il work-up prima dell'intervento."], "pazienti": ["[ROTULA INSTABILE NEI RAGAZZI] Una nuova misura alla risonanza aiuta la diagnosi.", "[LO STUDIO] 284 ginocchia analizzate, buoni risultati diagnostici.", "[PERCHÉ CONTA] Aiuta a capire meglio il problema prima di un'eventuale operazione."]}}};
var TAGS={"1": {"linkedin": "#MeniscalRepair #KneeSurgery #SportsMedicine", "instagram": "#Menisco #Ginocchio #ChirurgiaOrtopedica #Ortopedia #MedicinaSportiva #RadiceMeniscale #Artroscopia #Ricerca #SaluteDelGinocchio", "kw": "sutura radice menisco, rischio fallimento menisco"}, "2": {"linkedin": "#MeniscalRepair #KneeSurgery #ISAKOS", "instagram": "#Menisco #Ginocchio #Ortopedia #ChirurgiaArtroscopica #ComplicanzeChirurgiche #NerviPeriferici #MedicinaSportiva #Ricerca #SaluteDelGinocchio", "kw": "nervo dopo sutura menisco, complicanze riparazione menisco"}, "3": {"linkedin": "#HighTibialOsteotomy #KneeSurgery #OrthoTwitter", "instagram": "#Osteotomia #Ginocchio #Ortopedia #ArtrosiGinocchio #ChirurgiaOrtopedica #Ginocchiovaro #MedicinaSportiva #Ricerca #SaluteDelGinocchio", "kw": "osteotomia ginocchio varo, correzione asse gamba"}, "4": {"linkedin": "#UnicompartmentalKnee #KneeArthroplasty #Frailty", "instagram": "#ProtesiGinocchio #Monocompartimentale #Ortopedia #ArtrosiGinocchio #ChirurgiaOrtopedica #Fragilità #MedicinaGeriatrica #Ricerca #SaluteDelGinocchio", "kw": "protesi parziale ginocchio fragilità, monocompartimentale rischio"}, "5": {"linkedin": "#RoboticTKA #KneeArthroplasty #OrthoResearch", "instagram": "#ProtesiGinocchio #ChirurgiaRobotica #Ortopedia #ProtesiTotale #Cementazione #Robotica #MedicinaSportiva #Ricerca #SaluteDelGinocchio", "kw": "protesi ginocchio robot cemento, fissazione protesi robotica"}, "6": {"linkedin": "#Patellofemoral #KneeInstability #AJSM", "instagram": "#Rotula #Ginocchio #Ortopedia #InstabilitàRotulea #Adolescenti #RisonanzaMagnetica #MedicinaSportiva #Ricerca #SaluteDelGinocchio", "kw": "instabilità rotula adolescenti, risonanza ginocchio rotula"}};
var NLB={"1": {"prof": ["Sesso femminile, edema tibiale ed Outerbridge alto predicono il fallimento della radice", "Serie retrospettiva su 53 riparazioni della radice meniscale mediale posteriore: il 22,6% fallisce a 1 anno. Fallimento associato a sesso femminile (92% contro 63%, p=0,033), edema osseo tibiale preoperatorio (58% contro 12%, p=0,001) e Outerbridge mediale più alto (2,8 contro 1,9, p=0,015).", "Campione piccolo (53 pazienti, 12 fallimenti) e monocentrico: le stime restano imprecise, e l'estrusione preoperatoria — la variabile più discussa in letteratura — qui non risulta associata al fallimento."], "mix": ["Tre segnali prima dell'intervento aiutano a capire chi rischia di più con la sutura del menisco", "Uno studio su 53 pazienti operati di riparazione della radice del menisco interno mostra che in circa 1 caso su 5 la sutura non tiene entro un anno. Tre elementi visibili prima dell'intervento — essere donna, avere un gonfiore dell'osso alla risonanza, avere più usura della cartilagine — compaiono più spesso in chi poi fallisce.", "È uno studio piccolo, fatto in un solo centro: i numeri vanno presi come un primo segnale, non come una regola. Ma chi ha superato bene l'intervento è migliorato molto, sul dolore e sulla funzione, a due anni."], "paz": ["Prima di riparare il menisco interno, alcuni segnali aiutano a capire come andrà", "Un lavoro scientifico ha seguito 53 persone operate per riparare la radice del menisco interno, la parte che lo ancora all'osso. Nella maggior parte dei casi l'intervento ha funzionato bene, con netto miglioramento del dolore e della funzione a due anni.", "In una parte dei casi la riparazione non ha tenuto, e questo era più frequente in presenza di alcuni segnali visibili già prima dell'intervento. Sono indicazioni utili per il colloquio con il chirurgo, non certezze: lo studio è piccolo."], "kw": "sutura radice menisco, rischio fallimento menisco"}, "2": {"prof": ["Sintomi neurologici dopo sutura meniscale: una cornice per il sospetto clinico", "Current Concepts Review su meccanismi, strutture a rischio e work-up dei sintomi neurologici dopo riparazione meniscale: valutazione seriale come cardine, ecografia ad alta risoluzione e neurografia RM come complemento nei casi sospetti.", "Livello V, nessun dato originale: l'evidenza citata resta anatomica, tecnica o aneddotica, senza stime di incidenza affidabili né soglie diagnostiche validate."], "mix": ["Una guida per riconoscere i rari problemi ai nervi dopo la sutura del menisco", "Una rassegna di esperti mette insieme, per la prima volta in modo organico, come riconoscere i disturbi ai nervi — formicolii, dolore anomalo, difficoltà a muovere il piede — che possono comparire dopo una riparazione del menisco, complicanza rara ma da conoscere.", "Non porta dati nuovi propri: gli autori stessi dicono che la letteratura su questo tema è ancora scarsa, fatta soprattutto di casi isolati. È però la prima proposta di un percorso chiaro per capire quando preoccuparsi e come indagare."], "paz": ["Dopo la sutura del menisco, un raro disturbo ai nervi si può riconoscere presto", "In casi rari, dopo l'intervento per riparare il menisco può comparire un formicolio, un dolore insolito o una debolezza in una parte del piede o della gamba, dovuti a un piccolo disturbo del nervo vicino.", "Un gruppo di specialisti ha messo insieme le conoscenze su come riconoscere questi segnali il prima possibile e su quando serve un accertamento in più. È una complicanza non comune, e nella grande maggioranza dei casi si risolve da sola."], "kw": "nervo dopo sutura menisco, complicanze riparazione menisco"}, "3": {"prof": ["Nel varo severo, correggere di più non aumenta le complicanze dell'osteotomia", "Coorte di 109 ginocchia operate di osteotomia tibiale alta a V invertita: correzioni ≥13° non prolungano il consolidamento (12,7 contro 12,4 settimane) né aumentano le complicanze (4,1% contro 3,3%; RR 1,22, IC 95% 0,18-8,38 con potenza.py) rispetto a correzioni <13°.", "Livello III, singolo centro, tasso di complicanze basso in entrambi i gruppi: l'intervallo di confidenza sul rischio relativo non esclude un rischio anche molto più alto nella correzione ampia — un dato rassicurante ma non definitivo."], "mix": ["Correggere di più la gamba storta non sembra più rischioso, quando serve davvero", "In 109 interventi di correzione dell'asse della gamba (osteotomia) per artrosi da varo severo, chi ha ricevuto una correzione più grande — fino quasi a 19 gradi — non ha avuto tempi di guarigione dell'osso più lunghi né più complicazioni di chi ha ricevuto una correzione più piccola.", "Il numero di complicazioni osservate è basso in entrambi i gruppi, quindi lo studio non può escludere del tutto un rischio più alto nella correzione ampia: il segnale è incoraggiante, ma non definitivo."], "paz": ["Correggere bene la gamba storta, anche quando serve una correzione importante", "Quando il ginocchio è molto \"storto verso l'interno\" per l'artrosi, a volte serve correggere di molto l'asse della gamba con un intervento chiamato osteotomia. Uno studio su oltre cento interventi mostra che le correzioni più importanti guariscono bene quanto quelle più piccole, senza più complicazioni.", "È una buona notizia per chi ha un'artrosi già avanzata e ha bisogno di una correzione consistente: l'intervento resta sicuro anche in questi casi, anche se lo studio non può garantirlo con assoluta certezza."], "kw": "osteotomia ginocchio varo, correzione asse gamba"}, "4": {"prof": ["La fragilità preoperatoria predice la progressione laterale dopo la mono", "Coorte di 203 ginocchia con protesi monocompartimentale mediale, follow-up medio 70,8 mesi: la fragilità (Clinical Frailty Scale >3) predice in modo indipendente la progressione artrosica del compartimento laterale (OR 4,36; IC 95% 1,37-13,90; p=0,013), con punteggi funzionali finali significativamente peggiori.", "Dati radiografici a 5 anni disponibili solo per il 48,8% della coorte, possibile selezione; intervallo di confidenza ampio (1,37-13,90): la stima puntuale è netta ma poco precisa."], "mix": ["Chi arriva più fragile alla protesi parziale rischia di più sul compartimento sano", "In oltre duecento protesi parziali di ginocchio (solo il lato interno sostituito), i pazienti più fragili prima dell'intervento — misurati con una scala clinica semplice — hanno un rischio più che quadruplo di veder peggiorare, negli anni, anche il lato del ginocchio non operato.", "Lo studio segue i pazienti per quasi sei anni in media, ma i dati radiografici completi a cinque anni sono disponibili solo per metà della coorte: un limite da tenere presente nel leggere i numeri."], "paz": ["Prima della protesi parziale, la forma fisica generale conta anche per il futuro del ginocchio", "In chi riceve una protesi che sostituisce solo la parte interna del ginocchio, uno studio mostra che le persone più fragili — più anziane, con meno riserve fisiche — hanno più probabilità che, negli anni, si consumi anche l'altra parte del ginocchio, quella non sostituita.", "Non è una controindicazione all'intervento, ma un'informazione utile per capire in anticipo, insieme al chirurgo, quali aspettative avere nel tempo, specie nelle persone più fragili."], "kw": "protesi parziale ginocchio fragilità, monocompartimentale rischio"}, "5": {"prof": ["Cementata o non cementata nella robotica: l'evidenza resta troppo debole", "Revisione sistematica di 10 studi comparativi sulla fissazione nella protesi totale robot-assistita: RR di revisione a medio termine 0,63 (IC 95% 0,09-4,53), certezza GRADE molto bassa su ogni esito, nessun vantaggio dimostrato di una strategia sull'altra.", "Sintesi clinica a soli 3 studi per gli esiti principali, eterogeneità fino al 94,4% sul tempo operatorio: la scelta cementata/non cementata nella robotica resta, oggi, non guidata da prove solide."], "mix": ["Nella protesi robotica, fissare con o senza cemento: la scienza non ha ancora deciso", "Una revisione di dieci studi che confrontano la fissazione cementata e quella non cementata nella protesi di ginocchio robot-assistita non trova una strategia chiaramente migliore: né sulla necessità di reintervento, né sui tempi operatori.", "La certezza delle prove è definita dagli stessi autori \"molto bassa\" per tutti i risultati: significa che nuovi studi più grandi potrebbero cambiare completamente questa conclusione. Oggi la scelta resta clinica."], "paz": ["Protesi del ginocchio: fissarla con o senza cemento non cambia, per ora, i risultati noti", "Nella protesi di ginocchio guidata dal robot si può fissare l'impianto con il cemento osseo oppure senza. Una revisione di dieci studi scientifici non ha trovato prove sufficienti per dire quale delle due scelte dia risultati migliori nel tempo.", "Questo non significa che le due tecniche siano uguali: significa che, con le conoscenze attuali, non c'è ancora una risposta certa. La scelta resta affidata all'esperienza del chirurgo e alle caratteristiche del singolo paziente."], "kw": "protesi ginocchio robot cemento, fissazione protesi robotica"}, "6": {"prof": ["Un nuovo indice RM per l'instabilità femoro-rotulea negli adolescenti", "Studio caso-controllo su 284 ginocchia: il nuovo angolo di inclinazione del tendine rotuleo (PTIA) e la distanza PT-LTR discriminano l'instabilità femoro-rotulea con buona accuratezza (AUC 0,866 e 0,903), restando informativi anche a TT-TG normale.", "Studio diagnostico, nessun esito clinico o chirurgico valutato; riproducibilità inter-osservatore non riportata nell'abstract."], "mix": ["Una nuova misura sulla risonanza aiuta a capire perché la rotula esce dal suo posto", "In adolescenti con instabilità della rotula, un nuovo modo di misurare l'inclinazione del tendine sotto il ginocchio alla risonanza magnetica riesce a distinguere bene chi ha il problema da chi no, anche quando le misure classiche non bastano da sole.", "È uno strumento diagnostico in più per lo studio prima dell'intervento, non ancora collegato a un esito chirurgico: aiuta a capire meglio il quadro, non a decidere da solo l'operazione."], "paz": ["Una nuova misura alla risonanza aiuta a capire l'instabilità della rotula nei ragazzi", "Negli adolescenti la rotula può uscire dal suo alloggiamento naturale (instabilità femoro-rotulea). Uno studio ha messo a punto un nuovo modo di misurare, con la risonanza magnetica, come è orientato il tendine sotto il ginocchio, e questo aiuta a riconoscere meglio il problema.", "È un ulteriore strumento per lo studio del ginocchio prima di un'eventuale operazione di ricostruzione del legamento che stabilizza la rotula, non un esame da fare da solo per decidere l'intervento."], "kw": "instabilità rotula adolescenti, risonanza ginocchio rotula"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy, Sports Medicine, and Rehabilitation",h:"Chi rischia di più dopo la sutura della radice meniscale mediale",v:"Una serie retrospettiva monocentrica su 53 riparazioni della radice meniscale posteriore mediale identifica tre fattori legati al fallimento: sesso femminile, edema osseo tibiale preoperatorio ed Outerbridge mediale più alto.",ax:"Wynveen, Henson-Vendrell, Glover et al.",date:"set 2026",meta:"serie retrospettiva monocentrica, 53 pazienti · [IV]",pmid:'42719661',doi:'10.1002/ars2.70065',journal:"Arthroscopy, Sports Medicine, and Rehabilitation",authors:"Wynveen MC, Henson-Vendrell AM, Glover MA, Restrepo A, Recker AJ, Trasolini NA, Waterman BR, van der List JP",design:"Serie di casi retrospettiva monocentrica su pazienti sottoposti a riparazione artroscopica primaria della radice meniscale posteriore mediale in un centro di riferimento terziario (2017-2023), con almeno 1 anno di follow-up. Fallimento definito come ri-rottura meniscale e/o conversione a protesi di ginocchio, confermata clinicamente e con imaging. Analisi univariata (chi-quadro o test esatto di Fisher per le categoriche, t-test per le continue).",pop:"53 pazienti, età media 54±12 anni, BMI medio 33±8 kg/m², 69,8% donne.",results:"12 pazienti (22,6%) soddisfano i criteri di fallimento a un follow-up minimo di 1 anno. Il fallimento è associato a sesso femminile (92% contro 63%, p=0,033), edema osseo tibiale preoperatorio (58% contro 12%, p=0,001) e Outerbridge del comparto mediale più alto (2,8±0,9 contro 1,9±1,1, p=0,015). Età, BMI, metodo di fissazione ed estrusione preoperatoria non sono associati al fallimento. Nei pazienti con esito favorevole, la scala VAS scende da 4,9±3,1 a 2,1±2,2 e il SANE sale da 51,7±28,1 a 80,8±18,2 a 2 anni (p<0,001 per entrambi).",concl:"Gli autori concludono che, in questa piccola coorte, sesso femminile, edema osseo midollare tibiale preoperatorio e classificazione Outerbridge più alta sono predittori di fallimento, mentre età, BMI ed estrusione preoperatoria non lo sono; la riparazione, quando riesce, dà miglioramenti sintomatici e funzionali significativi a 2 anni.",limits:"Livello IV, serie retrospettiva monocentrica, senza gruppo di controllo · campione piccolo (53 pazienti, 12 fallimenti): le stime di associazione restano imprecise · l'estrusione preoperatoria, la variabile su cui la tensione T2b insiste di più, non risulta qui associata al fallimento — un dato che aggiunge complessità, non la risolve.",perte:"Tocca direttamente la tua tecnica di rifissazione transtibiale della radice meniscale mediale. Tre variabili preoperatorie facilmente disponibili — sesso, edema osseo alla RM, grado Outerbridge — offrono un primo profilo di rischio da discutere con la paziente prima dell'intervento, anche se il campione è troppo piccolo per un uso prescrittivo. Si aggiunge alla T2b sul carico degenerativo basale, ma da un angolo diverso: non è l'estrusione a spiegare qui il fallimento."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Journal of ISAKOS",h:"Danno ai nervi dopo la sutura meniscale: una guida per riconoscerlo",v:"Una Current Concepts Review propone per la prima volta un quadro strutturato — meccanismi, stratificazione del rischio, percorso diagnostico — per i sintomi neurologici dopo riparazione meniscale, complicanza rara ma finora priva di criteri condivisi.",ax:"Rivarola, Collazo, Palanconi et al.",date:"set 2026",meta:"revisione narrativa, current concepts review · [V]",pmid:'42722236',doi:'10.1016/j.jisako.2026.101217',journal:"Journal of ISAKOS",authors:"Rivarola H, Collazo C, Palanconi M, Meninato M, Rivarola B, Peñaherrera-Carrillo C, Castro AB, Urresta FE",design:"Current Concepts Review narrativa sui sintomi neurologici dopo riparazione meniscale: meccanismi lesionali, strutture nervose a rischio, correlazione con anestesia regionale, uso del laccio emostatico, posizionamento dei portali e tecnica di riparazione. Propone un framework di valutazione clinica seriale integrato con ecografia ad alta risoluzione, neurografia RM, studi di conduzione nervosa ed elettromiografia quando si sospetta una lesione strutturale.",pop:"Non applicabile: revisione narrativa, nessuna coorte propria.",results:"Non riporta dati quantitativi propri: sintetizza la letteratura disponibile, definita dagli stessi autori come composta prevalentemente da studi anatomici, note tecniche, case report e piccole serie, con stime di incidenza affidabili e soglie diagnostiche validate non ancora disponibili.",concl:"Gli autori propongono un framework esperto, stratificato per rischio, che integra fenotipo neurologico, fattori procedura-specifici, esame clinico seriale, imaging e valutazione elettrodiagnostica; sottolineano che il timing postoperatorio va letto come un modificatore del sospetto clinico, non come criterio isolato per distinguere una causa transitoria da una lesione strutturale.",limits:"Livello V, revisione narrativa: nessun dato originale né stima di incidenza aggregata · l'evidenza citata è dichiarata dagli stessi autori come limitata e prevalentemente aneddotica · nessuna soglia diagnostica validata proposta, solo un'euristica clinica.",perte:"Riguarda una complicanza rara ma reale della riparazione meniscale che pratichi regolarmente, comprese le suture e la rifissazione della radice. Non cambia la tecnica, ma offre per la prima volta un percorso strutturato di sospetto e valutazione da avere in mente quando un paziente riferisce disturbi sensitivi o motori dopo un intervento altrimenti riuscito."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Orthopaedic Journal of Sports Medicine",h:"Correggere di più il varo severo non costa di più in complicanze",v:"In 109 ginocchia operate di osteotomia tibiale alta a V invertita, correggere angoli ≥13° non prolunga i tempi di consolidamento né aumenta le complicanze rispetto a correzioni più piccole, nel varo severo.",ax:"Yasuda, Yabuuchi, Kondo et al.",date:"set 2026",meta:"studio di coorte, 109 ginocchia/96 pazienti · [III]",pmid:'42719410',doi:'10.1177/23259671261447195',journal:"Orthopaedic Journal of Sports Medicine",authors:"Yasuda K, Yabuuchi K, Kondo E, Onodera J, Sato D, Iwasaki N, Yagi T",design:"Studio di coorte su 109 ginocchia (96 pazienti) operate di osteotomia tibiale alta a V invertita (iVHTO) con placca a compressione bloccata, seguite fino a 24 mesi con un controllo finale fra 3 e 6 anni. Consolidamento osseo valutato con punteggio radiologico quantitativo. Confronto fra correzione ampia (angolo ≥13°, gruppo L, 49 ginocchia) e correzione più piccola (<13°, gruppo S, 60 ginocchia) su tempo di consolidamento, complicanze, punteggi funzionali e KOOS.",pop:"109 ginocchia di 96 pazienti con gonartrosi in varo severo.",results:"Il varo preoperatorio è significativamente maggiore nel gruppo L (p<0,001); l'allineamento postoperatorio è in valgo in entrambi i gruppi senza differenze significative. L'angolo di correzione va da 13° a 19° (media 15,6°) nel gruppo L e da 9° a 12° (media 10,5°) nel gruppo S. Nessuna differenza significativa fra i due gruppi su tempo di consolidamento (12,7 contro 12,4 settimane), tasso di complicanze (4,1% contro 3,3%; con `test/potenza.py` sui conteggi grezzi: rischio relativo 1,22, IC 95% 0,18-8,38), punteggio Lysholm (93 contro 96,5) e nessuna delle cinque sottoscale KOOS (es. sintomi: 83,6 contro 88). Entrambi i gruppi migliorano significativamente rispetto al preoperatorio.",concl:"Gli autori concludono che correzioni ampie (≥13°) con la tecnica iVHTO e placca bloccata non prolungano il consolidamento osseo, non aumentano le complicanze e non peggiorano gli esiti clinici rispetto a correzioni più piccole, nelle ginocchia artrosiche in varo severo.",limits:"Livello III, coorte non randomizzata, singolo centro · tasso di complicanze basso in entrambi i gruppi: con `test/potenza.py` l'intervallo di confidenza sul rischio relativo (0,18-8,38) non esclude né un forte vantaggio né un rischio quasi ottuplicato della correzione ampia · tecnica (iVHTO) e fissazione specifiche, non generalizzabili automaticamente ad altre osteotomie ad apertura mediale.",perte:"Riguarda la tua chirurgia correttiva nel varo severo: rassicura sul fatto che spingere la correzione quando serve — fino a 19° in questa casistica — non sembra pagare in termini di complicanze o consolidamento, sebbene il campione sia troppo piccolo per escludere con certezza un rischio più alto nelle correzioni ampie."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"The Journal of the American Academy of Orthopaedic Surgeons",h:"Il paziente fragile perde di più il compartimento laterale dopo la mono",v:"In 203 ginocchia operate di protesi monocompartimentale mediale, la fragilità preoperatoria predice in modo indipendente la progressione artrosica del compartimento laterale a un follow-up medio di quasi 6 anni.",ax:"Wang, Du, Li et al.",date:"set 2026",meta:"coorte retrospettiva monocentrica, 203 ginocchia/177 pazienti · [III]",pmid:'42720305',doi:'10.5435/JAAOS-D-25-01604',journal:"The Journal of the American Academy of Orthopaedic Surgeons",authors:"Wang Z, Du M, Li Z, An S, Cao G, Huang Y",design:"Studio retrospettivo monocentrico su pazienti consecutivi operati di protesi monocompartimentale mediale mobile Oxford Phase III (2016-2020), esclusi i casi con sovracorrezione coronale postoperatoria o estrusione meniscale laterale preoperatoria alla RM. Fragilità preoperatoria classificata con la Clinical Frailty Scale (CFS): robusti (CFS≤3) contro fragili (CFS>3). Esiti: angolo anca-ginocchio-caviglia, grado Kellgren-Lawrence laterale, Oxford Knee Score, Forgotten Joint Score, punteggio Kujala, complicanze, revisione o conversione a protesi totale. Analisi di regressione logistica univariata e multivariabile.",pop:"203 ginocchia di 177 pazienti (101 robusti, 102 fragili), follow-up medio 70,8 mesi.",results:"A parità di caratteristiche basali (tranne l'età), il gruppo fragile ha punteggi finali peggiori: Oxford Knee Score 39,39 contro 43,06 (p<0,001), Forgotten Joint Score 79,56 contro 89,40 (p<0,001), Kujala 59,88 contro 67,71 (p<0,001), con un guadagno di Oxford Knee Score inferiore (13,47 contro 18,72; p<0,001). Su 99/203 ginocchia con radiografie a 5 anni disponibili, la progressione del compartimento laterale (aumento di un grado Kellgren-Lawrence) compare nel 26,3% contro l'11,8% (p=0,001); all'analisi multivariabile la fragilità predice in modo indipendente la progressione (OR 4,36; IC 95% 1,37-13,90; p=0,013), con un gradiente di rischio crescente nei livelli più alti di fragilità (p=0,043).",concl:"Gli autori concludono che la fragilità preoperatoria, misurata con la Clinical Frailty Scale, è comune e associata in modo indipendente a un rischio più alto di progressione artrosica del compartimento laterale a medio termine dopo protesi monocompartimentale mediale, con un rischio che cresce ai livelli di fragilità più alti; propongono la stratificazione CFS come strumento pratico per il colloquio preoperatorio.",limits:"Livello III, coorte retrospettiva monocentrica · dati radiografici a 5 anni disponibili solo per 99 delle 203 ginocchia (48,8%), possibile selezione · intervallo di confidenza dell'odds ratio ampio (1,37-13,90): la stima puntuale è consistente ma poco precisa.",perte:"Riguarda direttamente la tua protesi monocompartimentale: uno strumento di fragilità semplice e già disponibile in ambulatorio (CFS) aiuta a impostare le aspettative preoperatorie sul rischio di dover poi convertire a protesi totale per usura del compartimento laterale, specie nei pazienti più anziani e fragili che spesso arrivano alla tua consultazione."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Robotic Surgery",h:"Cementata o non cementata nella protesi robotica: ancora non si sa",v:"Una revisione sistematica di 10 studi comparativi non trova evidenza sufficiente a favore della fissazione cementata o non cementata nella protesi totale robot-assistita: certezza molto bassa su ogni esito aggregato.",ax:"Lu, Rui, Wang et al.",date:"set 2026",meta:"revisione sistematica e meta-analisi, 10 studi/11 report · [II]",pmid:'42720876',doi:'10.1007/s11701-026-03858-9',journal:"Journal of Robotic Surgery",authors:"Lu X, Rui J, Wang X, Deng X, Dai H, Huang W",design:"Revisione sistematica e meta-analisi (PubMed, Embase, Web of Science, CENTRAL, ricerca fino al 29 luglio 2026, protocollo prospettico PROSPERO CRD420261446055) di studi comparativi fra fissazione non cementata e cementata nella protesi totale di ginocchio primaria robot-assistita. Modelli a effetti casuali con stima a massima verosimiglianza ristretta e correzione di Hartung-Knapp; rischio di bias con ROBINS-I, certezza con GRADE. 10 studi rappresentati da 11 report inclusi.",pop:"10 studi comparativi di protesi totale di ginocchio robot-assistita, cementata contro non cementata.",results:"Nella sintesi a tre studi, il rischio relativo aggregato per la revisione per tutte le cause a medio termine è 0,63 (IC 95% 0,09-4,53; I²=0%) e per la manipolazione in anestesia 1,03 (IC 95% 0,09-11,74; I²=31,6%). La stima suggerisce una possibile riduzione del tempo operatorio in alcuni contesti (differenza media -12,91 minuti; IC 95% -36,38/10,55; I²=94,4%), ma imprecisa e molto eterogenea. La durata della degenza è anch'essa imprecisa (differenza media -0,24 giorni; IC 95% -3,67/3,19; I²=0%). Le stime aggiustate da registro e istituzionali vanno in direzioni miste e sono tenute separate dai rischi grezzi. La certezza è molto bassa per ogni esito aggregato.",concl:"Gli autori concludono che l'evidenza osservazionale disponibile non è sufficiente a favorire una strategia di fissazione rispetto all'altra per sopravvivenza dell'impianto o rigidità dopo protesi totale robot-assistita; una eventuale riduzione del tempo operatorio dipende dal contesto e resta incerta.",limits:"Certezza GRADE molto bassa su ogni esito aggregato · sintesi a soli 3 studi per gli esiti clinici principali, con intervalli di confidenza larghissimi · eterogeneità molto alta (I² fino al 94,4%) sulla stima del tempo operatorio · nessuna distinzione esplicita per marca/sistema robotico nell'abstract, quindi non si sa se il VELYS sia rappresentato.",perte:"Tocca direttamente una scelta che affronti a ogni protesi robotica: cementare o no. Il messaggio onesto è che oggi la letteratura non ti dà una risposta netta — il rischio relativo di revisione (0,63) è compatibile sia con un vantaggio reale del non cementato sia con un rischio quasi quintuplicato, e lo stesso vale per il tempo operatorio. Nessuna delle due scelte è oggi sostenuta da prove solide: la decisione resta clinica, non guidata dall'evidenza."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"The American Journal of Sports Medicine",h:"Un nuovo angolo RM per misurare l'instabilità della rotula",v:"Uno studio caso-controllo su 284 ginocchia introduce un parametro RM basato sul tendine rotuleo, distinto dagli indici classici, con buona accuratezza diagnostica nell'instabilità femoro-rotulea degli adolescenti.",ax:"Crippa, Beltrame, Beber et al.",date:"set 2026",meta:"studio caso-controllo, 284 ginocchia · [III]",pmid:'42717417',doi:'10.1177/03635465261478742',journal:"The American Journal of Sports Medicine",authors:"Crippa M, Beltrame G, Beber SA, Matarangas AI, Lu S, Lijesen E, Jaramillo D, Green DW",design:"Studio caso-controllo su RM di 284 ginocchia (142 con instabilità femoro-rotulea, 142 controlli). Introduzione e validazione di due parametri basati sul tendine rotuleo — la distanza tendine rotuleo-cresta trocleare laterale (PT-LTR) e un nuovo angolo di inclinazione del tendine rotuleo (PTIA) — confrontati con sulcus angle, tilt rotuleo, angolo femoro-rotuleo laterale, distanza TT-TG e indice di Caton-Deschamps (CDI). Analisi di correlazione e curve ROC per l'accuratezza diagnostica, con sottoanalisi per TT-TG anomala, patella alta e displasia trocleare.",pop:"284 ginocchia: 142 con instabilità femoro-rotulea, 142 controlli.",results:"I pazienti con instabilità hanno PT-LTR (9,76±7,66 mm) e PTIA (22,76°±11,22°) significativamente più alti dei controlli (p<0,001). Entrambi i parametri correlano positivamente con tilt rotuleo, CDI e sulcus angle; la patella alta aumenta significativamente il PT-LTR (p<0,001). L'accuratezza diagnostica è buona per entrambi: area sotto la curva 0,903 per PT-LTR (soglia 4 mm) e 0,866 per PTIA (soglia 16°). I due parametri restano informativi anche quando il TT-TG è normale.",concl:"Gli autori concludono che PT-LTR e PTIA sono marcatori RM affidabili di instabilità femoro-rotulea negli adolescenti, complementari — non sostitutivi — dei parametri classici, con PTIA che aggiunge informazione sull'obliquità del tendine anche quando il TT-TG è nella norma.",limits:"Livello III, studio caso-controllo, misure eseguite da chirurghi ortopedici senza un confronto esplicito di riproducibilità inter-osservatore riportato nell'abstract · popolazione selezionata di pazienti chirurgici, non uno screening di popolazione generale · non valuta esiti clinici o chirurgici, solo accuratezza diagnostica.",perte:"Riguarda il work-up per instabilità femoro-rotulea nei tuoi pazienti adolescenti candidati a ricostruzione del MPFL: un parametro RM in più, centrato sul tendine rotuleo, da tenere presente quando il TT-TG da solo non spiega il quadro clinico — non cambia l'indicazione chirurgica, arricchisce la valutazione preoperatoria."}];
var SUGGQ=[{"k": "kol", "n": "Daniel W. Green", "w": "Hospital for Special Surgery, New York (Stati Uniti)", "r": "Autore senior dello studio di oggi sui nuovi indici RM per l'instabilità femoro-rotulea negli adolescenti: corrispondenza tecnica diretta con la tua pratica su MPFL e patologia femoro-rotulea nella fascia d'età 14+. Stessa istituzione (HSS) già nota per Gregory S. DiFelice: un secondo nome dello stesso centro, su un tema diverso — la patologia pediatrica/adolescente del ginocchio. Sostituisce la proposta invariata di Joong Il Kim (10 settembre)."}];
var BRIEF_TEXT="Sei lavori oggi, nessuno rosso, nessuno arancione. Il lavoro scelto è una serie retrospettiva su 53 riparazioni della radice meniscale posteriore mediale: il 22,6% fallisce entro un anno, e tre segnali preoperatori pesano di più — sesso femminile, edema osseo tibiale alla risonanza, e un grado di usura cartilaginea più alto nel comparto mediale. Sorprende quello che non conta: né l'età, né il peso corporeo, né l'estrusione preoperatoria, la variabile su cui insiste da luglio la tensione sulla radice meniscale. Quando la riparazione riesce, il miglioramento a due anni resta netto, sul dolore e sulla funzione. Una seconda scheda, sempre sul menisco, propone la prima cornice organica per riconoscere i rari sintomi neurologici dopo una riparazione. Nell'osteotomia tibiale alta per varo severo, correggere di più — fino a quasi 19 gradi — non costa in complicanze rispetto a correzioni più piccole, anche se il numero di eventi osservati resta troppo basso per escludere del tutto un rischio maggiore. Nella protesi monocompartimentale, la fragilità preoperatoria misurata con una scala clinica semplice predice un rischio più che quadruplo di progressione artrosica del compartimento laterale nel tempo. Sulla scelta fra fissazione cementata e non cementata nella protesi robotica, una revisione sistematica è onesta più che risolutiva: la certezza dell'evidenza resta molto bassa su ogni esito, e nessuna delle due strategie è oggi sostenuta da prove solide. Chiude la giornata un nuovo indice alla risonanza magnetica per l'instabilità femoro-rotulea negli adolescenti, utile nel work-up prima di una ricostruzione del legamento patello-femorale mediale. Il raccoglitore notturno delle fonti esterne non è passato per l'ottavo giorno consecutivo: richiami, congressi e società restano non verificati oggi.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Oggi partiamo dal lavoro scelto: una serie su 53 pazienti operati di riparazione della radice meniscale interna."}, {"chi": "B", "t": "Quella tecnica che usi tu, transtibiale?"}, {"chi": "A", "t": "Esatto. Il 22,6% fallisce entro un anno, e tre segnali prima dell'intervento pesano di più: essere donna, avere un gonfiore dell'osso alla risonanza, e più usura della cartilagine."}, {"chi": "B", "t": "E l'estrusione? Non era il punto centrale della tua tensione aperta da luglio?"}, {"chi": "A", "t": "Proprio per questo sorprende: qui non risulta associata al fallimento. Un angolo diverso dello stesso problema, non ancora una risposta."}, {"chi": "B", "t": "C'è dell'altro sul menisco oggi?"}, {"chi": "A", "t": "Sì, una rassegna propone per la prima volta una guida chiara per riconoscere i rari disturbi ai nervi dopo la riparazione meniscale."}, {"chi": "B", "t": "E sull'osteotomia, novità?"}, {"chi": "A", "t": "Buone: correggere molto il varo severo, anche fino a quasi diciannove gradi, non aumenta le complicanze rispetto a correzioni più piccole."}, {"chi": "B", "t": "E sulla protesi parziale?"}, {"chi": "A", "t": "La fragilità del paziente prima dell'intervento predice un rischio più che quadruplo di veder peggiorare, nel tempo, il lato non operato del ginocchio."}, {"chi": "B", "t": "Quindi conviene misurarla prima."}, {"chi": "A", "t": "Esatto, è uno strumento semplice, già disponibile in ambulatorio. Sulla protesi robotica, invece, una revisione sistematica ammette che non c'è ancora una risposta chiara fra fissazione cementata e non cementata."}, {"chi": "B", "t": "Quindi la scelta resta clinica."}, {"chi": "A", "t": "Per ora sì. E chiudiamo con un nuovo indice alla risonanza per l'instabilità della rotula negli adolescenti, utile prima di una ricostruzione del legamento patello-femorale."}, {"chi": "B", "t": "Il raccoglitore notturno ha funzionato stanotte?"}, {"chi": "A", "t": "No, ottavo giorno di fila che manca: richiami, congressi e società restano non verificati anche oggi."}];
